let palette = ["#046380", "#16193B", "#35478C", "#4E7AC7", "#7FB2F0", "#ADD5F7"];

let xCen, xCen2, xCen3;
let yCen, yCen2, yCen3;
let off = 0.0;
let angle;
let off2 = 0.0;
let angle2;
let inc = random(.0075);
let off3 = 0.0;
let angle3;
let inc2 = random(.0075);
let inc3 = random(.0075);
let count = 0;

function setup(){
  createCanvas(800, 800);
  background(255);
  noFill();
  xCen = width*.4;
  yCen = height*.4;
  xCen2 = width*random(.4);
  yCen2 = height*random(.4); 
  xCen3 = width*random(.4);
  yCen3 = height*random(.4);
}
function draw(){    

  if (count <= 3000){
    translate(width/2, height/2);

    if (count % int(random(50, 100)) == 0){
      stroke(palette[int(random(palette.length))], 10); 
    }

    bezier(0, 0, xCen3*cos(radians(angle3)), yCen3*sin(radians(angle3)), xCen2*cos(radians(angle2)), yCen2*sin(radians(angle2)), xCen*cos(radians(angle)), yCen*sin(radians(angle)));

    angle = noise(off) * width; 
    off += inc;   
    angle2 = noise(off2) * width;
    off2 += inc2;  
    angle3 = noise(off3) * width;
    off3 += inc3;
    translate(-width/2, 0);   
    count++;
  }
}

function mousePressed(){
  background(255);
  xCen2 = width*random(.4);
  yCen2 = height*random(.4);
  xCen3 = width*random(.4);
  yCen3 = height*random(.4); 
  inc = random(.005);
  inc2 = random(.005);
  inc3 = random(.005);
  count = 0;
}

function keyPressed(){
  if (key == 'p'){
    saveFrame("line-######.png");
  }
}
